<?php
require __DIR__.'/includes/bootstrap.php';
$cats=db()->query("SELECT id,name,image FROM categories WHERE is_active=1 ORDER BY sort_order,id")->fetchAll();
$banners=db()->query("SELECT title,subtitle,image_url,link_url FROM banners WHERE is_active=1 ORDER BY sort_order,id")->fetchAll();
$storeName=setting('store_name','الفخامة للشيشة والتبغ');$storeDesc=setting('store_description','اكتشف تجربة فاخرة لا مثيل لها');$logo=setting('store_logo');$hero=setting('hero_image');
if($hero && !empty($banners)) $banners[0]['image_url']=$hero;
if(!$banners)$banners=[['title'=>$storeName,'subtitle'=>$storeDesc,'image_url'=>$hero?:'assets/images/product-placeholder.svg','link_url'=>'#products']];
$products=db()->query("SELECT id,name,price,image_url,stock FROM products WHERE is_active=1 ORDER BY id DESC LIMIT 24")->fetchAll();
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#080706"><title><?=h($storeName)?></title><link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;900&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/css/store.css?v=52"></head><body><?php include __DIR__.'/includes/nav.php';?><section class="hero"><div class="hero-slides"><?php foreach($banners as $i=>$b):?><article class="hero-slide <?=$i===0?'active':''?>" style="--hero-image:url('<?=h($b['image_url'])?>')"><div class="hero-text"><small>مرحباً بكم في</small><h1><?=h($b['title'])?></h1><p><?=h($b['subtitle'])?></p><a class="gold" href="<?=h($b['link_url']?:'#products')?>">تسوق الآن　🛒</a></div></article><?php endforeach?></div><div class="dots"></div></section><section id="cats"><h2>✦　تسوّق حسب القسم　✦</h2><div class="carousel"><button id="left" aria-label="الأقسام السابقة">‹</button><div class="track" id="categoryTrack"><button class="cat all-cat active" data-id=""><span>✦</span><b>الكل</b></button><?php foreach($cats as $c):?><button class="cat" data-id="<?=$c['id']?>"><span><?php if($c['image']):?><img src="<?=h($c['image'])?>" alt=""><?php else:?>✧<?php endif?></span><b><?=h($c['name'])?></b></button><?php endforeach?></div><button id="right" aria-label="الأقسام التالية">›</button></div></section><section id="products"><h2 id="productsTitle">✦　أحدث المنتجات　✦</h2><div class="grid" id="productGrid"><?php foreach($products as $p):?><article><a href="product.php?id=<?=$p['id']?>"><img src="<?=h($p['image_url']?:'assets/images/product-placeholder.svg')?>" alt="<?=h($p['name'])?>"><h3><?=h($p['name'])?></h3></a><strong><?=money($p['price'])?></strong><?php if((int)$p['stock']>0):?><button class="gold add-to-cart" data-id="<?=$p['id']?>" data-name="<?=h($p['name'])?>" data-price="<?=h($p['price'])?>" data-stock="<?=$p['stock']?>" data-image="<?=h($p['image_url'])?>">أضف إلى السلة</button><?php else:?><span class="out-stock">غير متوفر</span><?php endif?><a class="details-link" href="product.php?id=<?=$p['id']?>">التفاصيل</a></article><?php endforeach?></div></section><?php include __DIR__.'/includes/footer.php';?><input type="hidden" id="cartCsrf" value="<?=h(csrf_token())?>"><script src="assets/js/store.js?v=52" defer></script></body></html>